<section class="page-head"><div><p class="eyebrow">ALIŞVERİŞ</p><h1>Sepetim</h1><p>Ürünlerinizi kontrol edip siparişinizi oluşturun.</p></div></section><?php if(!$cart): ?><div class="empty cart-empty"><h2>Sepetiniz boş</h2><p>Mağazaya dönerek ürünleri keşfedebilirsiniz.</p><a class="primary-link" href="<?= e(url()) ?>">Alışverişe başla</a></div><?php else: ?><div class="cart-layout"><div class="cart-lines"><?php foreach($cart as $item): ?><article class="cart-line"><div class="cart-thumb"><?php if($item['image']): ?><img src="<?= e($item['image']) ?>" alt="<?= e($item['name']) ?>"><?php else: ?>GAME<?php endif; ?></div><div class="cart-line-info"><h3><a href="<?= e(url('product/'.rawurlencode($item['slug']))) ?>"><?= e($item['name']) ?></a></h3><p><?= $item['quantity'] ?> adet · <?= $item['delivery_type']==='automatic'?'Otomatik kod':'Manuel teslimat' ?></p><strong><?= number_format($item['line_total'],2,',','.') ?> ₺</strong></div><form method="post" action="<?= e(url('cart/remove')) ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button class="link-danger" type="submit">Kaldır</button></form></article><?php endforeach; ?></div><aside class="cart-summary"><h2>Sipariş özeti</h2><form method="post" action="<?= e(url('cart/coupon')) ?>" class="coupon-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><label>İndirim kuponu<input name="coupon_code" maxlength="64" value="<?= e($couponQuote['coupon']['code']??($_SESSION['coupon_code']??'')) ?>" placeholder="Kupon kodunuz" required></label><button type="submit">Kuponu uygula</button></form><?php if(!empty($couponQuote)): ?><p><span>Kupon indirimi</span><strong>-<?= number_format((float)$couponQuote['discount'],2,',','.') ?> ₺</strong></p><form method="post" action="<?= e(url('cart/coupon/remove')) ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="link-danger" type="submit">Kuponu kaldır</button></form><?php endif; ?><p><span>Ara toplam</span><strong><?= number_format($total,2,',','.') ?> ₺</strong></p><p><span>Genel toplam</span><strong class="detail-price"><?= number_format((float)($couponQuote['total']??$total),2,',','.') ?> ₺</strong></p><a class="primary-link" href="<?= e(url('checkout')) ?>">Siparişi tamamla</a></aside></div><?php endif; ?>